function setLang(l){
  localStorage.setItem('ptaLang',l);
  document.documentElement.lang=l;
  document.body.classList.toggle('en-mode',l==='en');
  document.querySelectorAll('[data-i18n]').forEach(e=>{
    const k=e.getAttribute('data-i18n');
    if(T[l][k]){
      if(T[l][k].indexOf('\n')>-1){e.innerHTML=T[l][k].replace(/\n/g,'<br>');}
      else{e.textContent=T[l][k];}
    }
  });
  document.querySelectorAll('[data-i18n-ph]').forEach(e=>{
    const k=e.getAttribute('data-i18n-ph');
    if(T[l][k]){e.setAttribute('placeholder',T[l][k]);}
  });
  document.getElementById('btn-es').classList.toggle('active',l==='es');
  document.getElementById('btn-en').classList.toggle('active',l==='en');
}
const sl=localStorage.getItem('ptaLang')||'es';
if(sl!=='es')setLang(sl);

/* scroll shadow */
const hdr=document.getElementById('site-header');
window.addEventListener('scroll',()=>{hdr.classList.toggle('scrolled',window.scrollY>10);},{passive:true});

/* burger */
const brg=document.getElementById('burger'),mm=document.getElementById('mobile-menu');
brg.addEventListener('click',()=>{const o=brg.classList.toggle('open');brg.setAttribute('aria-expanded',o);mm.classList.toggle('open',o);});
mm.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{brg.classList.remove('open');mm.classList.remove('open');brg.setAttribute('aria-expanded','false');}));

/* scroll reveal */
const ro=new IntersectionObserver((es)=>{
  es.forEach((e,i)=>{
    if(e.isIntersecting){setTimeout(()=>e.target.classList.add('visible'),i*80);ro.unobserve(e.target);}
  });
},{threshold:0.12});
document.querySelectorAll('.reveal').forEach(e=>ro.observe(e));

/* ─── GATES ANTI-BOT: teléfono y email ensamblados por JS ───
   Los datos NO existen como texto plano en el HTML. */
function phoneParts(){return ['689','270','8845'];}
function phoneDisplay(){const p=phoneParts();return '('+p[0]+') '+p[1]+'-'+p[2];}
function phoneHref(){return ['te','l:','+1'].join('')+phoneParts().join('');}
function emailAddr(){return ['yudit','@','pulidotax','.com'].join('');}

/* ─── FORMULARIO DE CONSULTA (envía a su correo vía FormSubmit, sin exponerlo) ─── */
function sendLead(e){
  e.preventDefault();
  const btn=document.getElementById('lf-submit');
  const ok=document.getElementById('lf-ok');
  const err=document.getElementById('lf-err');
  ok.style.display='none';err.style.display='none';
  btn.disabled=true;btn.style.opacity='.6';
  const data={
    nombre:document.getElementById('lf-nombre').value,
    telefono:document.getElementById('lf-telefono').value,
    correo:document.getElementById('lf-correo').value,
    pregunta:document.getElementById('lf-pregunta').value,
    _subject:'Nueva consulta desde pulidotax.com',
    _captcha:'false',
    _template:'table'
  };
  fetch('https://formsubmit.co/ajax/'+emailAddr(),{
    method:'POST',
    headers:{'Content-Type':'application/json','Accept':'application/json'},
    body:JSON.stringify(data)
  }).then(r=>{
    if(!r.ok)throw new Error();
    document.getElementById('lead-form').reset();
    ok.style.display='block';
  }).catch(()=>{
    err.style.display='block';
  }).finally(()=>{
    btn.disabled=false;btn.style.opacity='1';
  });
  return false;
}

/* footer contact gate — también ensamblado por JS */
function revealFooterContact(e){
  e.preventDefault();
  const em=emailAddr();
  const fe=document.getElementById('footer-email');
  const ea=document.createElement('a');
  ea.href='mailto:'+em;ea.textContent=em;
  fe.appendChild(ea);
  const fp=document.getElementById('footer-phone');
  const pa=document.createElement('a');
  pa.href=phoneHref();pa.textContent=phoneDisplay();
  fp.appendChild(pa);
  document.getElementById('footer-gate-btn').style.display='none';
  fe.style.display='list-item';
  fp.style.display='list-item';
}

/* ─── FAQ ACORDEONES ─── */
function toggleFaq(btn){
  const item=btn.closest('.faq-item');
  const ans=item.querySelector('.faq-a');
  const isOpen=item.classList.contains('open');
  document.querySelectorAll('.faq-item.open').forEach(o=>{
    o.classList.remove('open');
    o.querySelector('.faq-a').style.maxHeight='0';
    o.querySelector('.faq-q').setAttribute('aria-expanded','false');
  });
  if(!isOpen){
    item.classList.add('open');
    ans.style.maxHeight=ans.scrollHeight+'px';
    btn.setAttribute('aria-expanded','true');
  }
}
